#region Using declarations
using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.ComponentModel.DataAnnotations;
using System.Globalization;
using System.IO;
using NinjaTrader.Cbi;
using NinjaTrader.Data;
using NinjaTrader.NinjaScript;
using NinjaTrader.NinjaScript.Strategies;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    /// <summary>
    /// R072 Stage-2 execution parity REPLAY for MES.
    ///
    /// IMPORTANT:
    /// - The 145 frozen 2020-2025 R072 signals are generated by the Python
    ///   R063/H081 research engine and loaded from CSV.
    /// - This file validates NinjaTrader execution/timing/news handling.
    /// - It is NOT the final live C# implementation of the R063 regime engine.
    /// - 2026 is forbidden.
    ///
    /// After replay parity, the optional catastrophe stop can be enabled at
    /// 0.70 ATR using the frozen ATR value stored with each Python signal.
    /// </summary>
    public class R072SignalReplayParity : Strategy
    {
        private const string LongSignal="R072_LONG";
        private const string ShortSignal="R072_SHORT";

        private sealed class SignalRow
        {
            public DateTime SignalEt;
            public int Direction;
            public double ExpectedEntry;
            public double AtrPrev;
        }

        private sealed class NewsWindow
        {
            public DateTime StartEt;
            public DateTime EndEt;
        }

        private readonly Dictionary<DateTime,SignalRow> signals=
            new Dictionary<DateTime,SignalRow>();
        private readonly Dictionary<DateTime,List<NewsWindow>> newsByDate=
            new Dictionary<DateTime,List<NewsWindow>>();

        private TimeZoneInfo easternTimeZone;
        private TimeZoneInfo applicationTimeZone;
        private bool configurationValid;

        private DateTime activeSignalEt=DateTime.MinValue;
        private double activeAtrPrev=double.NaN;

        protected override void OnStateChange()
        {
            if(State==State.SetDefaults)
            {
                Name="R072SignalReplayParity";
                Description="R072 2020-2025 frozen-signal NinjaTrader execution parity replay.";
                Calculate=Calculate.OnBarClose;
                EntriesPerDirection=1;
                EntryHandling=EntryHandling.AllEntries;
                IsExitOnSessionCloseStrategy=true;
                ExitOnSessionCloseSeconds=30;
                StartBehavior=StartBehavior.WaitUntilFlat;
                TimeInForce=TimeInForce.Gtc;
                BarsRequiredToTrade=20;

                TimeExitMinutes=30;
                UseNewsExit=true;
                RequireNewsFile=true;
                NewsCsvPath=string.Empty;

                RequireSignalFile=true;
                SignalCsvPath=string.Empty;

                UseCatastropheStop=false;
                CatastropheStopAtr=0.70;
                StrictParity2020To2025=true;
                DebugPrints=false;
            }
            else if(State==State.DataLoaded)
            {
                configurationValid=true;
                try
                {
                    easternTimeZone=TimeZoneInfo.FindSystemTimeZoneById("Eastern Standard Time");
                    applicationTimeZone=NinjaTrader.Core.Globals.GeneralOptions.TimeZoneInfo;
                }
                catch(Exception ex)
                {
                    configurationValid=false;
                    Print("R072 CONFIG ERROR timezone: "+ex.Message);
                    return;
                }

                if(BarsPeriod.BarsPeriodType!=BarsPeriodType.Minute || BarsPeriod.Value!=1)
                {
                    configurationValid=false;
                    Print("R072 CONFIG ERROR: primary series must be 1-minute.");
                }

                LoadSignals();
                if(UseNewsExit) LoadNews();

                Print(string.Format(CultureInfo.InvariantCulture,
                    "R072 replay loaded. signals={0}; news windows={1}; App TZ={2}; TradingHours={3}",
                    signals.Count,CountNewsWindows(),
                    applicationTimeZone==null?"null":applicationTimeZone.Id,
                    Bars.TradingHours==null?"null":Bars.TradingHours.Name));
            }
        }

        protected override void OnBarUpdate()
        {
            if(!configurationValid) return;

            DateTime et=ToEastern(Time[0]);
            if(StrictParity2020To2025 && (et.Year<2020 || et.Year>2025)) return;

            if(Position.MarketPosition!=MarketPosition.Flat)
            {
                if(UseNewsExit && IsNewsFlatBoundary(et))
                {
                    if(Position.MarketPosition==MarketPosition.Long)
                        ExitLong("R072_NEWS_EXIT",LongSignal);
                    else if(Position.MarketPosition==MarketPosition.Short)
                        ExitShort("R072_NEWS_EXIT",ShortSignal);
                    return;
                }

                if(activeSignalEt!=DateTime.MinValue && et>=activeSignalEt.AddMinutes(TimeExitMinutes))
                {
                    if(Position.MarketPosition==MarketPosition.Long)
                        ExitLong("R072_TIME_EXIT",LongSignal);
                    else if(Position.MarketPosition==MarketPosition.Short)
                        ExitShort("R072_TIME_EXIT",ShortSignal);
                    return;
                }
            }

            if(Position.MarketPosition!=MarketPosition.Flat) return;

            SignalRow row;
            if(!signals.TryGetValue(et,out row)) return;

            activeSignalEt=et;
            activeAtrPrev=row.AtrPrev;

            if(row.Direction==1)
            {
                if(UseCatastropheStop && !double.IsNaN(activeAtrPrev) && activeAtrPrev>0)
                {
                    int ticks=Math.Max(1,(int)Math.Ceiling((CatastropheStopAtr*activeAtrPrev)/TickSize-1e-12));
                    SetStopLoss(LongSignal,CalculationMode.Ticks,ticks,false);
                }
                EnterLong(1,LongSignal);
            }
            else
            {
                if(UseCatastropheStop && !double.IsNaN(activeAtrPrev) && activeAtrPrev>0)
                {
                    int ticks=Math.Max(1,(int)Math.Ceiling((CatastropheStopAtr*activeAtrPrev)/TickSize-1e-12));
                    SetStopLoss(ShortSignal,CalculationMode.Ticks,ticks,false);
                }
                EnterShort(1,ShortSignal);
            }

            if(DebugPrints)
                Print(string.Format(CultureInfo.InvariantCulture,
                    "R072 REPLAY SIGNAL {0} {1} expectedEntry={2:F2} atr={3:F4}",
                    et.ToString("yyyy-MM-dd HH:mm:ss"),
                    row.Direction==1?"LONG":"SHORT",
                    row.ExpectedEntry,row.AtrPrev));
        }

        protected override void OnExecutionUpdate(
            Execution execution,string executionId,double price,int quantity,
            MarketPosition marketPosition,string orderId,DateTime time)
        {
            if(!DebugPrints || execution==null || execution.Order==null) return;
            Print(string.Format(CultureInfo.InvariantCulture,
                "R072 EXEC {0} name={1} price={2:F2} qty={3} position={4}",
                ToEastern(time).ToString("yyyy-MM-dd HH:mm:ss"),
                execution.Order.Name,price,quantity,marketPosition));
        }

        private DateTime ToEastern(DateTime applicationTime)
        {
            DateTime u=DateTime.SpecifyKind(applicationTime,DateTimeKind.Unspecified);
            return TimeZoneInfo.ConvertTime(u,applicationTimeZone,easternTimeZone);
        }

        private bool IsNewsFlatBoundary(DateTime et)
        {
            List<NewsWindow> w;
            if(!newsByDate.TryGetValue(et.Date,out w)) return false;
            for(int i=0;i<w.Count;i++)
                if(et==w[i].StartEt) return true;
            return false;
        }

        private int CountNewsWindows()
        {
            int n=0;
            foreach(KeyValuePair<DateTime,List<NewsWindow>> kv in newsByDate) n+=kv.Value.Count;
            return n;
        }

        private void LoadSignals()
        {
            signals.Clear();
            if(string.IsNullOrWhiteSpace(SignalCsvPath) || !File.Exists(SignalCsvPath))
            {
                Print("R072 SIGNAL FILE missing: "+(SignalCsvPath??string.Empty));
                if(RequireSignalFile) configurationValid=false;
                return;
            }

            try
            {
                using(StreamReader reader=new StreamReader(SignalCsvPath))
                {
                    string header=reader.ReadLine();
                    string line;
                    while((line=reader.ReadLine())!=null)
                    {
                        if(string.IsNullOrWhiteSpace(line)) continue;
                        string[] p=line.Split(',');
                        if(p.Length<6) continue;

                        DateTime dt;
                        int direction;
                        double entry,atr;

                        if(!DateTime.TryParseExact(p[0].Trim(),"yyyy-MM-dd HH:mm:ss",
                            CultureInfo.InvariantCulture,DateTimeStyles.None,out dt)) continue;
                        if(!int.TryParse(p[2].Trim(),NumberStyles.Integer,CultureInfo.InvariantCulture,out direction)) continue;
                        if(!double.TryParse(p[4].Trim(),NumberStyles.Any,CultureInfo.InvariantCulture,out entry)) entry=double.NaN;
                        if(!double.TryParse(p[5].Trim(),NumberStyles.Any,CultureInfo.InvariantCulture,out atr)) atr=double.NaN;

                        signals[dt]=new SignalRow{
                            SignalEt=dt,Direction=direction,ExpectedEntry=entry,AtrPrev=atr
                        };
                    }
                }
            }
            catch(Exception ex)
            {
                Print("R072 SIGNAL FILE error: "+ex.Message);
                if(RequireSignalFile) configurationValid=false;
            }
        }

        private void LoadNews()
        {
            newsByDate.Clear();
            if(string.IsNullOrWhiteSpace(NewsCsvPath) || !File.Exists(NewsCsvPath))
            {
                Print("R072 NEWS FILE missing: "+(NewsCsvPath??string.Empty));
                if(RequireNewsFile) configurationValid=false;
                return;
            }

            try
            {
                using(StreamReader reader=new StreamReader(NewsCsvPath))
                {
                    string header=reader.ReadLine();
                    string line;
                    while((line=reader.ReadLine())!=null)
                    {
                        if(string.IsNullOrWhiteSpace(line)) continue;
                        string[] p=line.Split(',');
                        if(p.Length<2) continue;
                        DateTime s,e;
                        if(!DateTime.TryParseExact(p[0].Trim(),"yyyy-MM-dd HH:mm:ss",
                            CultureInfo.InvariantCulture,DateTimeStyles.None,out s)) continue;
                        if(!DateTime.TryParseExact(p[1].Trim(),"yyyy-MM-dd HH:mm:ss",
                            CultureInfo.InvariantCulture,DateTimeStyles.None,out e)) continue;

                        List<NewsWindow> w;
                        if(!newsByDate.TryGetValue(s.Date,out w))
                        {
                            w=new List<NewsWindow>();
                            newsByDate[s.Date]=w;
                        }
                        w.Add(new NewsWindow{StartEt=s,EndEt=e});
                    }
                }
            }
            catch(Exception ex)
            {
                Print("R072 NEWS FILE error: "+ex.Message);
                if(RequireNewsFile) configurationValid=false;
            }
        }

        #region Properties
        [NinjaScriptProperty]
        [Range(1,120)]
        [Display(Name="Time exit minutes",Order=1,GroupName="Frozen R072 execution")]
        public int TimeExitMinutes{get;set;}

        [NinjaScriptProperty]
        [Display(Name="Use catastrophe stop",Order=2,GroupName="Frozen R072 execution")]
        public bool UseCatastropheStop{get;set;}

        [NinjaScriptProperty]
        [Range(0.05,3.00)]
        [Display(Name="Catastrophe stop ATR",Order=3,GroupName="Frozen R072 execution")]
        public double CatastropheStopAtr{get;set;}

        [NinjaScriptProperty]
        [Display(Name="Require signal file",Order=1,GroupName="Parity files")]
        public bool RequireSignalFile{get;set;}

        [NinjaScriptProperty]
        [Display(Name="Signal CSV path",Order=2,GroupName="Parity files")]
        public string SignalCsvPath{get;set;}

        [NinjaScriptProperty]
        [Display(Name="Use news exit",Order=3,GroupName="Parity files")]
        public bool UseNewsExit{get;set;}

        [NinjaScriptProperty]
        [Display(Name="Require news file",Order=4,GroupName="Parity files")]
        public bool RequireNewsFile{get;set;}

        [NinjaScriptProperty]
        [Display(Name="News CSV path",Order=5,GroupName="Parity files")]
        public string NewsCsvPath{get;set;}

        [NinjaScriptProperty]
        [Display(Name="Strict parity 2020-2025",Order=1,GroupName="Safety")]
        public bool StrictParity2020To2025{get;set;}

        [NinjaScriptProperty]
        [Display(Name="Debug prints",Order=2,GroupName="Safety")]
        public bool DebugPrints{get;set;}
        #endregion
    }
}
